#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package NetMQ@4.0.1 #:package System.Threading.Channels@8.0.0 #:package Microsoft.Extensions.ObjectPool@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using System.Threading.Channels; using NetMQ; using NetMQ.Sockets; using System.Threading.Tasks.Dataflow;  // ZeroMQ消息处理器 public class ZeroMqMessageProcessor : IAsyncDisposable {     private readonly ObjectPool<Memory<byte>> _memoryPool;     private readonly Channel<ReadOnlyMemory<byte>> _messageChannel;     private readonly ResponseSocket _responseSocket;     private readonly ThreadLocal<Span<byte>> _threadLocalBuffer;          public ZeroMqMessageProcessor(string connectionString)     {         _memoryPool = new DefaultObjectPool<Memory<byte>>(             new DefaultPooledObjectPolicy<Memory<byte>>(), 1000);                      _messageChannel = Channel.CreateUnbounded<ReadOnlyMemory<byte>>();         _responseSocket = new ResponseSocket(connectionString);         _threadLocalBuffer = new ThreadLocal<Span<byte>>(() => stackalloc byte[1024]);                  _ = ProcessMessagesAsync();     }      // 使用零拷贝接收消息     public async Task ReceiveMessagesAsync(CancellationToken ct = default)     {         while (!ct.IsCancellationRequested)         {             var memory = _memoryPool.Get();             try             {                 var received = _responseSocket.ReceiveFrameBytes();                 memory.Span[..received.Length].CopyFrom(received);                 await _messageChannel.Writer.WriteAsync(memory[..received.Length], ct);             }             finally             {                 _memoryPool.Return(memory);             }         }     }      private async Task ProcessMessagesAsync()     {         await foreach (var message in _messageChannel.Reader.ReadAllAsync())         {             using var memory = _memoryPool.Get();             message.CopyTo(memory.Span);                          // 处理消息逻辑...             var response = ProcessMessage(memory.Span);                          // 零拷贝发送响应             _responseSocket.SendFrame(response);         }     }      private ReadOnlySpan<byte> ProcessMessage(Span<byte> message)     {         // 消息处理逻辑...         return _threadLocalBuffer.Value;     }      public async ValueTask DisposeAsync()     {         _responseSocket.Dispose();         await _messageChannel.Writer.CompleteAsync();     } }  // 启动配置 var builder = WebApplication.CreateBuilder();  // 配置ZeroMQ服务 builder.Services.AddSingleton<ZeroMqMessageProcessor>(sp =>      new ZeroMqMessageProcessor("@tcp://localhost:5555"));  var app = builder.Build();  // 启动消息接收 var processor = app.Services.GetRequiredService<ZeroMqMessageProcessor>(); _ = processor.ReceiveMessagesAsync();  app.MapGet("/", () => "ZeroMQ Message Processor Running"); app.Run();   public class ZeroMqMultiProtocolSupport {     private readonly Dictionary<string, NetMQSocket> _sockets = new();     private readonly ObjectPool<Memory<byte>> _memoryPool;      public ZeroMqMultiProtocolSupport(ObjectPool<Memory<byte>> memoryPool)     {         _memoryPool = memoryPool;     }      public void AddEndpoint(string protocol, string address)     {         switch (protocol.ToLower())         {             case "ipc":                 _sockets[protocol] = new PairSocket($"@ipc://{address}");                 break;             case "tcp":                 _sockets[protocol] = new PairSocket($"@tcp://{address}");                 break;             case "ws":                 _sockets[protocol] = new PairSocket($"@ws://{address}");                 break;             default:                 throw new ArgumentException($"Unsupported protocol: {protocol}");         }     }          public async Task SendMulticastAsync(ReadOnlyMemory<byte> message)     {         using var memory = _memoryPool.Get();         message.CopyTo(memory.Span);                  foreach (var socket in _sockets.Values)         {             socket.SendFrame(memory.Span);         }     } }   public class ZeroMqMessageSecurity {     private readonly AesGcm _aesGcm;     private readonly ThreadLocal<Span<byte>> _encryptionBuffer;      public ZeroMqMessageSecurity(byte[] key)     {         _aesGcm = new AesGcm(key);         _encryptionBuffer = new ThreadLocal<Span<byte>>(() => stackalloc byte[1024]);     }      public Span<byte> Encrypt(Span<byte> plaintext)     {         var buffer = _encryptionBuffer.Value;         var nonce = RandomNumberGenerator.GetBytes(12);         var tag = new byte[16];                  _aesGcm.Encrypt(nonce, plaintext, buffer, tag);         return buffer[..plaintext.Length];     }          public Span<byte> Compress(Span<byte> input)     {         using var memory = MemoryPool<byte>.Shared.Rent(input.Length);         using var gzip = new GZipStream(new MemoryStream(memory.Memory.Span.ToArray()), CompressionLevel.Optimal);                  gzip.Write(input);         return memory.Memory.Span[..input.Length];     } }   public class ZeroMqClusterManager {     private readonly List<RouterSocket> _nodes = new();     private readonly RingBuffer<byte[]> _messageBuffer;     private readonly DisruptorNet<byte[]> _disruptor;      public ZeroMqClusterManager()     {         _messageBuffer = new RingBuffer<byte[]>(1024);         _disruptor = new DisruptorNet<byte[]>(_messageBuffer);                  _disruptor.HandleEventsWith(new ClusterMessageHandler());     }      public void AddNode(string address)     {         var socket = new RouterSocket();         socket.Bind(address);         _nodes.Add(socket);     }      public void Broadcast(byte[] message)     {         using var scope = _disruptor.PublishEvent();         scope.Event().CopyFrom(message);     } }   public class ZeroMqMetrics {     private readonly Meter _meter;     private readonly Counter<int> _messagesProcessed;     private readonly Histogram<double> _processingLatency;      public ZeroMqMetrics(IMeterFactory meterFactory)     {         _meter = meterFactory.Create("ZeroMQ");         _messagesProcessed = _meter.CreateCounter<int>("messages.processed");         _processingLatency = _meter.CreateHistogram<double>("processing.latency.ms");     }      public void RecordMessage(int size, double latency)     {         _messagesProcessed.Add(1);         _processingLatency.Record(latency);     } }  // 在Startup中注册 builder.Services.AddOpenTelemetry()     .WithMetrics(metrics => metrics         .AddMeter("ZeroMQ")         .AddPrometheusExporter());
